def classify(case):
    sample = case['sample']
    method = case['method']
    if method == 'RUB_BETWEEN_FINGERS' and case.get('grating_sound'):
        quality = 'BEST_SAND'
        mortar = True
    elif method == 'WHITE_CLOTH_SHAKE' and case.get('removable_stain_or_particles'):
        quality = 'EARTHY_BUT_USABLE'
        mortar = True
    else:
        raise ValueError('source test does not license fit')
    if case['use'] == 'MORTAR':
        return quality + '_AND_FIT_MORTAR' if quality == 'BEST_SAND' else 'FIT_MORTAR_BUT_NOT_BEST_SAND'
    if case['source'] == 'SEA_SAND' and case['use'] == 'VAULTING_WALL':
        return 'REJECT_VAULTING_WALL'
    if case.get('age') == 'OLD_EXPOSED' and case['use'] == 'HEAVY_LOAD_WALL':
        return 'REJECT_HEAVY_LOAD_WALL'
    if case['source'] == 'PIT_SAND' and case['use'] == 'PLASTER':
        return 'UNFIT_PLASTER'
    if case['source'] == 'RIVER_SAND' and case['use'] == 'PLASTER':
        return 'FIT_PLASTER_AFTER_TEMPERING'
    return 'USE_SCOPE_UNRESOLVED'

result = {
  'rub_test_mortar': classify({'sample':'S1','method':'RUB_BETWEEN_FINGERS','grating_sound':True,'use':'MORTAR','source':'PIT_SAND'}),
  'cloth_test_mortar': classify({'sample':'S2','method':'WHITE_CLOTH_SHAKE','removable_stain_or_particles':True,'use':'MORTAR','source':'EARTHY_SAND'}),
  'sea_vault_context': classify({'sample':'S3','method':'WHITE_CLOTH_SHAKE','removable_stain_or_particles':True,'use':'VAULTING_WALL','source':'SEA_SAND'}),
  'old_pit_heavy_context': classify({'sample':'S4','method':'RUB_BETWEEN_FINGERS','grating_sound':True,'use':'HEAVY_LOAD_WALL','source':'PIT_SAND','age':'OLD_EXPOSED'})
}
